DSA.PY_SRC = {"tracer":"\"\"\"Runs a Python program line by line and records every step as JSON.\n\nThe visualizers in the lessons replay these steps. The same file runs in two places:\n  * on your computer, when tools/build.mjs pre-computes the lesson animations\n  * inside the browser (Pyodide), when you press \"Edit & visualize\"\n\nA line can carry a note for the step explanation:   x = a + b   #: add {a} and {b}\nText after \"#:\" is an f-string, evaluated with the variables just BEFORE the line runs.\n\"\"\"\n\nimport io\nimport json\nimport re\nimport sys\nimport types\n\nFILENAME = \"<lesson>\"\nNOTE_RE = re.compile(r\"\\s*#:\\s?(.*)$\")\nDEF_RE = re.compile(r\"(def|class)\\s+(\\w+)\")\nSKIP_TYPES = (types.FunctionType, types.ModuleType, type, types.BuiltinFunctionType, types.MethodType)\n\n\nclass StepLimit(Exception):\n    pass\n\n\nclass Tracer:\n    def __init__(self, src, max_steps=1000):\n        self.max_steps = max_steps\n        self.notes = {}\n        self.lines = src.split(\"\\n\")\n        for i, line in enumerate(self.lines, 1):\n            m = NOTE_RE.search(line)\n            if m:\n                self.notes[i] = m.group(1)\n        self.steps = []\n        self.ids = {}\n        self.keep = []  # keeps objects alive so Python never reuses their id()\n        self.out = io.StringIO()\n\n    # ---------- turning Python values into JSON ----------\n    def ref_id(self, obj):\n        key = id(obj)\n        if key not in self.ids:\n            self.ids[key] = len(self.ids) + 1\n            self.keep.append(obj)\n        return self.ids[key]\n\n    def enc(self, v, heap):\n        if v is None or isinstance(v, (bool, int)):\n            return v\n        if isinstance(v, float):\n            if v != v or v in (float(\"inf\"), float(\"-inf\")):\n                return {\"f\": repr(v)}\n            return v\n        if isinstance(v, str):\n            return v\n        rid = self.ref_id(v)\n        out = {\"ref\": rid}\n        if rid in heap:\n            return out\n        entry = {}\n        heap[rid] = entry\n        name = type(v).__name__\n        if isinstance(v, dict):\n            entry[\"t\"] = \"dict\"\n            if name != \"dict\":\n                entry[\"cls\"] = name\n            entry[\"v\"] = [[self.enc(k, heap), self.enc(x, heap)] for k, x in list(v.items())[:200]]\n        elif isinstance(v, (list, tuple)) or name == \"deque\":\n            entry[\"t\"] = \"tuple\" if isinstance(v, tuple) else (\"deque\" if name == \"deque\" else \"list\")\n            entry[\"v\"] = [self.enc(x, heap) for x in list(v)[:300]]\n        elif isinstance(v, (set, frozenset)):\n            entry[\"t\"] = \"set\"\n            try:\n                items = sorted(v)\n            except TypeError:\n                items = sorted(v, key=repr)\n            entry[\"v\"] = [self.enc(x, heap) for x in items[:200]]\n        elif hasattr(v, \"__dict__\") and not isinstance(v, SKIP_TYPES):\n            entry[\"t\"] = \"obj\"\n            entry[\"cls\"] = name\n            entry[\"v\"] = {k: self.enc(x, heap) for k, x in vars(v).items() if not k.startswith(\"_\")}\n        else:\n            entry[\"t\"] = \"other\"\n            entry[\"repr\"] = repr(v)[:80]\n        return out\n\n    # ---------- recording ----------\n    def visible_frames(self, frame):\n        stack = []\n        while frame is not None:\n            if frame.f_code.co_filename == FILENAME:\n                stack.append(frame)\n            frame = frame.f_back\n        stack.reverse()\n        return stack\n\n    def note_for(self, frame, lineno):\n        tpl = self.notes.get(lineno)\n        if not tpl:\n            return None\n        try:\n            return eval(\"f\" + repr(tpl), frame.f_globals, dict(frame.f_locals))\n        except Exception:\n            return None\n\n    def record(self, frame, kind, arg=None):\n        if len(self.steps) >= self.max_steps:\n            raise StepLimit()\n        heap = {}\n        frames = []\n        for f in self.visible_frames(frame):\n            fn = f.f_code.co_name\n            scope = f.f_globals if fn == \"<module>\" else f.f_locals\n            names = {}\n            for k, v in list(scope.items()):\n                if k.startswith(\"_\") or isinstance(v, SKIP_TYPES):\n                    continue\n                names[k] = self.enc(v, heap)\n            frames.append({\"fn\": \"global\" if fn == \"<module>\" else fn, \"vars\": names})\n        step = {\"l\": frame.f_lineno, \"k\": kind, \"s\": frames, \"h\": heap, \"o\": self.out.getvalue()}\n        if kind == \"line\":\n            note = self.note_for(frame, frame.f_lineno)\n            if note:\n                step[\"n\"] = note\n            elif frame.f_code.co_name == \"<module>\":\n                m = DEF_RE.match(self.lines[frame.f_lineno - 1]) if frame.f_lineno <= len(self.lines) else None\n                if m:\n                    step[\"n\"] = (f\"Python remembers the function {m.group(2)}() — its body runs only when you call it\"\n                                 if m.group(1) == \"def\" else f\"Python creates the class {m.group(2)}\")\n        elif kind == \"call\":\n            args = \", \".join(f\"{k}={self.short(v)}\" for k, v in list(frame.f_locals.items())[: frame.f_code.co_argcount])\n            step[\"n\"] = f\"Call {frame.f_code.co_name}({args})\"\n        elif kind == \"return\":\n            if frame.f_code.co_name == \"<module>\":\n                step[\"n\"] = \"Program finished\"\n            else:\n                step[\"r\"] = self.enc(arg, heap)\n                step[\"n\"] = f\"{frame.f_code.co_name} returns {self.short(arg)}\"\n        elif kind == \"exc\":\n            step[\"n\"] = f\"{arg[0].__name__}: {arg[1]}\"\n        self.steps.append(step)\n\n    @staticmethod\n    def short(v):\n        if hasattr(v, \"__dict__\") and not isinstance(v, SKIP_TYPES):\n            val = getattr(v, \"val\", getattr(v, \"value\", None))\n            return f\"{type(v).__name__}({val!r})\" if val is not None else type(v).__name__\n        text = repr(v)\n        return text if len(text) <= 40 else text[:37] + \"...\"\n\n    def trace(self, frame, event, arg):\n        code = frame.f_code\n        if code.co_filename != FILENAME:\n            return None\n        if code.co_name != \"<module>\" and (code.co_name.startswith((\"<\", \"_\")) or not code.co_flags & 1):\n            return None  # skip lambdas, generator expressions, class bodies and _helpers/__init__\n        if event == \"call\" and code.co_name != \"<module>\":\n            self.record(frame, \"call\")\n        elif event == \"line\":\n            self.record(frame, \"line\")\n        elif event == \"return\":\n            self.record(frame, \"return\", arg)\n        elif event == \"exception\" and arg[0] is not StepLimit:\n            self.record(frame, \"exc\", arg)\n        return self.trace\n\n    def run(self, src):\n        error = None\n        truncated = False\n        g = {\"__name__\": \"__main__\", \"__builtins__\": __builtins__}\n        old_out = sys.stdout\n        sys.stdout = self.out\n        try:\n            code = compile(src, FILENAME, \"exec\")\n            sys.settrace(self.trace)\n            try:\n                exec(code, g)\n            finally:\n                sys.settrace(None)\n        except StepLimit:\n            truncated = True\n        except SyntaxError as e:\n            error = f\"SyntaxError on line {e.lineno}: {e.msg}\"\n        except Exception as e:  # show the error as the last step\n            error = f\"{type(e).__name__}: {e}\"\n        finally:\n            sys.stdout = old_out\n        if self.steps and self.steps[-1][\"k\"] == \"exc\" and error is None:\n            pass\n        # drop the exception steps that Python reports again for every frame while unwinding\n        cleaned = []\n        for s in self.steps:\n            if s[\"k\"] == \"exc\" and cleaned and cleaned[-1][\"k\"] == \"exc\":\n                continue\n            cleaned.append(s)\n        return {\"steps\": cleaned, \"error\": error, \"truncated\": truncated, \"out\": self.out.getvalue()}\n\n\ndef display_code(src):\n    \"\"\"The source the learner sees: same lines, with the #: notes removed.\"\"\"\n    return \"\\n\".join(NOTE_RE.sub(\"\", line).rstrip() for line in src.split(\"\\n\"))\n\n\ndef run(src, max_steps=1000):\n    src = src.strip(\"\\n\")\n    result = Tracer(src, max_steps).run(src)\n    result[\"code\"] = display_code(src)\n    return json.dumps(result, separators=(\",\", \":\"))\n\n\nif __name__ == \"__main__\":\n    print(run(sys.stdin.read(), int(sys.argv[1]) if len(sys.argv) > 1 else 1000))\n","check":"\"\"\"Test helper used by every workbook file (and by the practice editor in the browser).\n\nYou don't need to read this file to do the exercises — but you can, it's plain Python.\n\"\"\"\n\nimport copy\nimport json\nimport sys\nimport traceback\n\n\n# ───────────── Node classes used by linked-list and tree problems ─────────────\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\n    def __repr__(self):\n        return f\"ListNode({self.val})\"\n\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\n    def __repr__(self):\n        return f\"TreeNode({self.val})\"\n\n\ndef build_linked(values):\n    \"\"\"[1, 2, 3] -> 1 -> 2 -> 3 (returns the head node, or None for [])\"\"\"\n    dummy = ListNode()\n    tail = dummy\n    for v in values:\n        tail.next = ListNode(v)\n        tail = tail.next\n    return dummy.next\n\n\ndef build_cycle(values, pos):\n    \"\"\"Linked list whose last node points back to index `pos` (-1 = no cycle).\"\"\"\n    head = build_linked(values)\n    if pos < 0 or head is None:\n        return head\n    nodes = []\n    node = head\n    while node:\n        nodes.append(node)\n        node = node.next\n    nodes[-1].next = nodes[pos]\n    return head\n\n\ndef linked_to_list(head, limit=10_000):\n    out = []\n    while head is not None and len(out) < limit:\n        out.append(head.val)\n        head = head.next\n    return out\n\n\ndef build_tree(values):\n    \"\"\"LeetCode style level-order list -> tree.  [1, 2, 3, None, 4] means:\n           1\n          / \\\\\n         2   3\n          \\\\\n           4\n    \"\"\"\n    if not values or values[0] is None:\n        return None\n    root = TreeNode(values[0])\n    queue = [root]\n    i = 1\n    for node in queue:\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n        if i >= len(values):\n            break\n    return root\n\n\ndef tree_to_list(root):\n    \"\"\"Tree -> LeetCode style level-order list (trailing None removed).\"\"\"\n    out = []\n    queue = [root]\n    for node in queue:\n        if node is None:\n            out.append(None)\n            continue\n        out.append(node.val)\n        queue.append(node.left)\n        queue.append(node.right)\n    while out and out[-1] is None:\n        out.pop()\n    return out\n\n\ndef find_node(root, val):\n    if root is None or root.val == val:\n        return root\n    return find_node(root.left, val) or find_node(root.right, val)\n\n\nCONVERT_IN = {\n    \"linked\": build_linked,\n    \"tree\": build_tree,\n    \"cycle\": lambda pair: build_cycle(pair[0], pair[1]),\n}\nCONVERT_OUT = {\n    \"linked\": linked_to_list,\n    \"tree\": tree_to_list,\n    \"node\": lambda n: None if n is None else n.val,\n}\n\n\n# ───────────── comparing answers ─────────────\ndef normalize(x):\n    if isinstance(x, (list, tuple)):\n        return [normalize(v) for v in x]\n    if isinstance(x, (set, frozenset)):\n        return sorted(normalize(v) for v in x)\n    if isinstance(x, dict):\n        return {k: normalize(v) for k, v in x.items()}\n    return x\n\n\ndef _sort_key(v):\n    return json.dumps(v, sort_keys=True)\n\n\ndef same(got, expected, compare=\"exact\"):\n    got = normalize(got)\n    if compare == \"float\":\n        if isinstance(got, list):\n            return len(got) == len(expected) and all(abs(a - b) < 1e-5 for a, b in zip(got, expected))\n        return isinstance(got, (int, float)) and abs(got - expected) < 1e-5\n    if compare == \"sorted\":\n        return isinstance(got, list) and sorted(got, key=_sort_key) == sorted(expected, key=_sort_key)\n    if compare == \"nested\":  # order doesn't matter at either level, e.g. [[1,2],[3]] == [[3],[2,1]]\n        if not isinstance(got, list) or not all(isinstance(g, list) for g in got):\n            return False\n        a = sorted((sorted(g, key=_sort_key) for g in got), key=_sort_key)\n        b = sorted((sorted(e, key=_sort_key) for e in expected), key=_sort_key)\n        return a == b\n    if compare == \"outer\":  # inner lists keep their order, outer order doesn't matter\n        return isinstance(got, list) and sorted(got, key=_sort_key) == sorted(expected, key=_sort_key)\n    return got == expected\n\n\n# ───────────── running tests ─────────────\nclass TooLong(Exception):\n    pass\n\n\ndef _guard(budget):\n    count = [0]\n\n    def tracer(frame, event, arg):\n        if event == \"line\":\n            count[0] += 1\n            if count[0] > budget:\n                raise TooLong(\"Your code ran too many steps (over 3 million lines) — an infinite loop, \"\n                              \"or too slow for this big input? Think about the Big-O.\")\n        return tracer\n\n    return tracer\n\n\ndef py_repr(v, limit=300):\n    if isinstance(v, dict) and \"__py__\" in v:\n        return v[\"__py__\"]\n    text = repr(v)\n    return text if len(text) <= limit else text[: limit - 20] + f\" … ({len(text)} characters)\"\n\n\ndef materialize(a):\n    \"\"\"Test inputs like {\"__py__\": \"list(range(100000))\"} are built by Python (big inputs for speed tests).\"\"\"\n    if isinstance(a, dict) and \"__py__\" in a:\n        return eval(a[\"__py__\"], {\"__builtins__\": __builtins__})\n    return a\n\n\ndef run_test(target, test, compare=\"exact\", convert=None, inplace=None, budget=3_000_000):\n    \"\"\"Runs one test. `target` is a function, or a class for design problems.\"\"\"\n    convert = convert or {}\n    result = {\"ok\": False, \"error\": None}\n    old = sys.gettrace()\n    try:\n        if \"ops\" in test:  # design problem, LeetCode style: [\"MinStack\",\"push\",\"top\"], [[],[1],[]]\n            result[\"input\"] = f\"{test['ops']}\\n{test['args']}\"\n            result[\"expected\"] = py_repr(test[\"expect\"])\n            got = []\n            obj = None\n            sys.settrace(_guard(budget))\n            try:\n                for op, args in zip(test[\"ops\"], test[\"args\"]):\n                    if obj is None:\n                        obj = target(*copy.deepcopy(args))\n                        got.append(None)\n                    else:\n                        got.append(getattr(obj, op)(*copy.deepcopy(args)))\n            finally:\n                sys.settrace(old)\n            result[\"got\"] = py_repr(got)\n            result[\"ok\"] = same(got, test[\"expect\"], compare)\n            return result\n\n        result[\"input\"] = \", \".join(py_repr(a) for a in test[\"args\"])\n        args = [materialize(a) for a in copy.deepcopy(test[\"args\"])]\n        kinds = convert.get(\"args\") or []\n        call_args = [CONVERT_IN[kinds[i]](a) if i < len(kinds) and kinds[i] else a for i, a in enumerate(args)]\n        expected = materialize(test[\"expect\"])\n        result[\"expected\"] = py_repr(expected) if \"anyOf\" not in test else \" or \".join(map(py_repr, test[\"anyOf\"]))\n        sys.settrace(_guard(budget))\n        try:\n            got = target(*call_args)\n        finally:\n            sys.settrace(old)\n        if inplace is not None:\n            got = call_args[inplace]\n        if convert.get(\"ret\"):\n            got = CONVERT_OUT[convert[\"ret\"]](got)\n        result[\"got\"] = py_repr(got)\n        options = test.get(\"anyOf\", [expected])\n        result[\"ok\"] = any(same(got, e, compare) for e in options)\n    except TooLong as e:\n        result[\"error\"] = str(e)\n    except RecursionError:\n        result[\"error\"] = \"RecursionError: too many nested calls — check your base case\"\n    except Exception as e:  # show the learner the real error, with the line in their code\n        where = \"\"\n        for fr in traceback.extract_tb(e.__traceback__):\n            if not fr.filename.endswith(\"_check.py\"):\n                where = f\"  (line {fr.lineno})\"\n        result[\"error\"] = f\"{type(e).__name__}: {e}{where}\"\n    finally:\n        sys.settrace(old)\n    return result\n\n\ndef run_all(namespace, name, tests, compare=\"exact\", convert=None, inplace=None):\n    \"\"\"Used by the browser: returns JSON with one result per test.\"\"\"\n    target = namespace.get(name)\n    if target is None:\n        return json.dumps({\"fatal\": f\"I can't find `{name}` — did you rename or delete it?\"})\n    return json.dumps({\"results\": [run_test(target, t, compare, convert, inplace) for t in tests]})\n\n\ndef check(target, tests, compare=\"exact\", convert=None, inplace=None):\n    \"\"\"Used by the workbook files: prints ✅ / ❌ for each problem (details for the first failing test).\"\"\"\n    name = getattr(target, \"__name__\", str(target))\n    results = [run_test(target, t, compare, convert, inplace) for t in tests]\n    passed = sum(r[\"ok\"] for r in results)\n    if passed == len(tests):\n        print(f\"✅ {name}: all {passed} tests pass\")\n        return True\n    first = next(i for i, r in enumerate(results) if not r[\"ok\"])\n    r = results[first]\n    print(f\"{'⬜' if passed == 0 else '🟨'} {name}: {passed}/{len(tests)} tests pass — first failing test (#{first + 1}):\")\n    print(f\"       input:    {r.get('input')}\")\n    print(f\"       expected: {r.get('expected')}\")\n    if r[\"error\"]:\n        print(f\"       error:    {r['error']}\")\n    else:\n        print(f\"       got:      {r.get('got')}\")\n    return False\n"}
